export function pickQuestions(work='math',count=3,offset=0){const pool=WORKS[work]?.questions;if(!pool)throw new Error('Неизвестная работа');return Array.from({length:Math.min(count,pool.length)},(_,i)=>pool[(i+offset)%pool.length]);}
